"""Lab 2: a retrieval pipeline, measured. Two chunkers, three retrievers, a re-ranker, then grounded answers
with citations that are checked. Run offline by default; add --live to generate answers with Claude."""

import re
from pathlib import Path

import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer

from llm import LIVE, ask

QUESTIONS = [  # question, a phrase the right chunk contains
    ("At what vibration level does a turbine shut down automatically?", "7.1 mm/s"),
    ("Who authorises a controlled shutdown?", "authorised by the shift supervisor"),
    ("When is the weekly maintenance window?", "Tuesday from 22:00"),
    ("How quickly must a P2 work order be completed?", "complete within 2 days"),
    ("What is the lowest level the reservoir may be operated at?", "312 metres"),
    ("How long do we keep turbine sensor data?", "retained for five years"),
    ("What is the deadline for reporting an incident that injured someone?", "within 24 hours"),
    ("Which extension reaches the control room?", "extension 4400"),
    ("Can I go into the turbine pit by myself?", "Never enter the turbine pit alone"),
    ("How often are bearings checked?", "every six months"),
]


def documents():
    """The handbook's documents, stored in one file and separated by '=== name ===' lines."""
    parts = re.split(r"^=== (\S+) ===$", Path("handbook.md").read_text(), flags=re.M)
    return {parts[i]: parts[i + 1].strip() + "\n" for i in range(1, len(parts), 2)}


def fixed_chunks(docs, size=160, overlap=40):
    chunks = []
    for name, text in docs.items():
        flat = " ".join(text.split())
        for start in range(0, len(flat), size - overlap):
            chunks.append({"doc": name, "section": f"chars {start}-{start + size}", "text": flat[start:start + size]})
    return chunks


def heading_chunks(docs):
    """One chunk per section, with the document title and heading prepended as context."""
    # TODO: split each document at its "## " headings (re.split(r"\n## ", text)[1:]). For each section, the
    #       heading is its first line and the body the rest; make a chunk {"doc": name, "section": heading,
    #       "text": f"{title} > {heading}: {body on one line}"}, where title is the document's first line without "# ".
    return fixed_chunks(docs)


class Retriever:
    def __init__(self, chunks, kind):
        self.chunks = chunks
        if kind == "words":
            self.vec = TfidfVectorizer(stop_words="english", sublinear_tf=True)
        else:   # character n-grams: tolerant of different word forms ("checked" / "checks")
            self.vec = TfidfVectorizer(analyzer="char_wb", ngram_range=(3, 5), sublinear_tf=True)
        self.matrix = self.vec.fit_transform([c["text"] for c in chunks])

    def rank(self, query):
        scores = (self.matrix @ self.vec.transform([query]).T).toarray().ravel()
        return list(np.argsort(-scores, kind="stable"))


def rrf(rankings, k=60):
    """Reciprocal rank fusion: each list adds 1 / (k + rank) for every item it ranks."""
    # TODO: for every ranking, add 1 / (k + rank) to each item's score (rank counts from 1); return the items
    #       sorted by total score, highest first (break ties by item number)
    return rankings[0]


STOP = {"the", "a", "an", "is", "at", "of", "to", "do", "we", "be", "by", "in", "can", "i", "what", "who", "how",
        "when", "which", "that", "may", "does", "for", "must", "into", "go", "myself", "level", "long"}


def stem(word):
    for suffix in ("ing", "ed", "es", "s"):
        if word.endswith(suffix) and len(word) - len(suffix) >= 4:
            return word[: -len(suffix)]
    return word


def terms(text):
    return {stem(w) for w in re.findall(r"[a-z0-9.]+", text.lower()) if w not in STOP}


def rerank(query, chunks, candidates, top=3):
    """A cross-scorer: looks at the query and each candidate together (here, the share of the query's terms it
    contains). A cross-encoder model or an LLM plays this role in production, on the top candidates only."""
    q = terms(query)
    scored = sorted(candidates, key=lambda i: (-len(q & terms(chunks[i]["text"])) / max(len(q), 1),
                                               candidates.index(i)))
    return scored[:top]


def evaluate(chunks, ranker):
    hits, reciprocal = 0, 0.0
    for question, answer in QUESTIONS:
        ranking = ranker(question)
        found = [r for r, i in enumerate(ranking[:10], 1) if answer.lower() in chunks[i]["text"].lower()]
        hits += bool(found) and found[0] <= 3
        reciprocal += 1 / found[0] if found else 0.0
    return hits / len(QUESTIONS), reciprocal / len(QUESTIONS)


def answer(question, chunks, top):
    sources = "\n".join(f"[{n}] ({chunks[i]['doc']} > {chunks[i]['section']}) {chunks[i]['text']}"
                        for n, i in enumerate(top, 1))
    if LIVE:
        return ask("Answer only from the numbered sources. Cite each claim like [1]. If the sources don't "
                   "contain the answer, say you don't know.", f"<sources>\n{sources}\n</sources>\n\n{question}")
    body = chunks[top[0]]["text"].split(": ", 1)[-1]          # offline: quote the best sentence of source 1
    best = max(re.split(r"(?<=\.)\s", body), key=lambda s: len(terms(question) & terms(s)))
    return f"{best} [1]"


def citations_ok(reply, chunks, top):
    # TODO: find every [n] in the reply; True only if there is at least one and each n is between 1 and len(top)
    return True


def main():
    docs = {k: v for k, v in documents().items() if k != "supplier_bulletin"}
    print(f"{len(docs)} documents")
    for chunk_name, chunks in [("fixed 160 chars", fixed_chunks(docs)), ("by heading", heading_chunks(docs))]:
        words, chars = Retriever(chunks, "words"), Retriever(chunks, "chars")
        rankers = {
            "words (TF-IDF)": words.rank,
            "char n-grams": chars.rank,
            "hybrid (RRF)": lambda q: rrf([words.rank(q), chars.rank(q)]),
            "hybrid + rerank": lambda q: (lambda c: rerank(q, chunks, c[:8]) + c[8:])(rrf([words.rank(q), chars.rank(q)])),
        }
        for name, ranker in rankers.items():
            hit, mrr = evaluate(chunks, ranker)
            print(f"{chunk_name:<16} {len(chunks):3d} chunks  {name:<16} hit@3 {hit:.1f}  MRR {mrr:.2f}")

    chunks = heading_chunks(docs)
    words, chars = Retriever(chunks, "words"), Retriever(chunks, "chars")
    question = "How quickly must a P2 work order be completed?"
    top = rerank(question, chunks, rrf([words.rank(question), chars.rank(question)])[:8])
    reply = answer(question, chunks, top)
    print("Q:", question)
    print("A:", reply)
    print("Citations point at retrieved sources:", citations_ok(reply, chunks, top))


if __name__ == "__main__":
    main()

"""Capstone skeleton: a multi-agent research assistant over the plant handbook. Replace each TODO with your
own design; keep the offline mode working so the evaluation runs without a key, and add --live for Claude."""

import json
import re
import sys
from pathlib import Path

LIVE = "--live" in sys.argv


def load_handbook():
    """The handbook's documents, stored in one file and separated by '=== name ===' lines."""
    parts = re.split(r"^=== (\S+) ===$", Path("handbook.md").read_text(), flags=re.M)
    return {parts[i]: parts[i + 1].strip() + "\n" for i in range(1, len(parts), 2)}


def input_guard(task):
    """TODO: topic and action checks, PII redaction, length limits. Return (allowed, cleaned_task, reason)."""
    return True, task, ""


def plan(task):
    """Orchestrator. TODO: split the task into sub-questions, as structured output (a list of strings)."""
    return [task]


def research(question, corpus):
    """Researcher agent. TODO: screen untrusted documents, retrieve with hybrid search and re-ranking, and answer
    with citations from the retrieved chunks only. Return {"question", "answer", "citations": [...]}."""
    return {"question": question, "answer": "TODO", "citations": []}


def write_brief(task, findings):
    """Writer agent. TODO: combine the findings into a brief that keeps every claim's citation."""
    return "TODO: brief for " + task


def review(brief, findings):
    """Reviewer (reflection). TODO: check grounding, citations and policy; return a list of problems, empty if fine."""
    return []


def run(task, corpus, max_revisions=2):
    allowed, task, reason = input_guard(task)
    if not allowed:
        return f"Refused: {reason}"
    findings = [research(q, corpus) for q in plan(task)]
    brief = write_brief(task, findings)
    for _ in range(max_revisions):
        problems = review(brief, findings)
        if not problems:
            break
        brief = write_brief(task + "\nFix: " + "; ".join(problems), findings)
    return brief


def evaluate():
    corpus = load_handbook()
    for case in json.loads(Path("research_tasks.json").read_text()):
        brief = run(case["task"], corpus)
        missing = [m for m in case["must_include"] if m.lower() not in brief.lower()]
        leaked = [m for m in case["must_not_include"] if m.lower() in brief.lower()]
        print(f"{'PASS' if not missing and not leaked else 'FAIL'}  missing {missing}  forbidden {leaked}")


if __name__ == "__main__":
    evaluate()
